import { createFileRoute } from "@tanstack/react-router";
import { Minus, Plus } from "lucide-react";
import { useState } from "react";

// @ts-expect-error - Route will be generated by TanStack Router plugin
export const Route = createFileRoute("/booking")({
	component: BookingPage,
});

interface CartItem {
	productId: string;
	name: string;
	price: number;
	quantity: number;
}

function BookingPage() {
	const [cart, setCart] = useState<CartItem[]>([]);
	const [showCart, setShowCart] = useState(false);

	const settings = {
		title: "YumiPOS Booking",
		description: "Pemesanan online mudah dan cepat",
		isActive: true,
	};

	const products = [
		{ _id: "1", name: "Produk 1", price: 25000, description: "Deskripsi produk 1" },
		{ _id: "2", name: "Produk 2", price: 30000, description: "Deskripsi produk 2" },
		{ _id: "3", name: "Produk 3", price: 15000, description: "Deskripsi produk 3" },
	];

	const addToCart = (product: { _id: string; name: string; price: number }) => {
		setCart((prev) => {
			const existing = prev.find((item) => item.productId === product._id);
			if (existing) {
				return prev.map((item) =>
					item.productId === product._id
						? { ...item, quantity: item.quantity + 1 }
						: item
				);
			}
			return [...prev, { productId: product._id, name: product.name, price: product.price, quantity: 1 }];
		});
	};

	const updateQuantity = (productId: string, delta: number) => {
		setCart((prev) =>
			prev
				.map((item) => {
					if (item.productId === productId) {
						return { ...item, quantity: Math.max(0, item.quantity + delta) };
					}
					return item;
				})
				.filter((item) => item.quantity > 0)
		);
	};

	const cartTotal = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
	const cartCount = cart.reduce((sum, item) => sum + item.quantity, 0);

	if (!settings?.isActive) {
		return (
			<div className="flex h-screen items-center justify-center bg-gray-50 p-4">
				<div className="text-center">
					<h1 className="text-2xl font-bold text-gray-800">Halaman Tidak Aktif</h1>
					<p className="text-gray-500">Maaf, halaman pemesanan sedang tidak tersedia.</p>
				</div>
			</div>
		);
	}

	return (
		<div className="min-h-screen bg-gray-50 pb-32">
			<div className="h-32 w-full bg-gradient-to-r from-gray-800 to-gray-900" />

			<div className="mx-auto max-w-md px-4">
				<div className="relative -mt-16 mb-8 text-center">
					<div className="mx-auto h-32 w-32 overflow-hidden rounded-full border-4 border-white bg-white shadow-lg">
						<div className="flex h-full w-full items-center justify-center bg-gray-100 text-3xl font-bold text-gray-400">
							{settings.title?.charAt(0) || "Y"}
						</div>
					</div>
					<h1 className="mt-4 text-2xl font-bold text-gray-900">{settings.title}</h1>
					{settings.description && (
						<p className="mt-2 text-sm text-gray-600">{settings.description}</p>
					)}
				</div>

				<div className="space-y-6">
					<h2 className="text-lg font-bold text-gray-900">Menu Pilihan</h2>
					<div className="grid gap-4">
						{products.map((product) => (
							<div
								key={product._id}
								className="flex items-center gap-4 rounded-2xl bg-white p-4 shadow-sm"
							>
								<div className="h-20 w-20 flex-shrink-0 overflow-hidden rounded-xl bg-gray-100">
									<div className="flex h-full w-full items-center justify-center text-2xl font-bold text-gray-300">
										{product.name.charAt(0)}
									</div>
								</div>
								<div className="flex-1">
									<h3 className="font-bold text-gray-900">{product.name}</h3>
									<p className="text-sm text-gray-500">{product.description}</p>
									<p className="mt-1 font-bold text-gray-800">
										Rp {product.price.toLocaleString("id-ID")}
									</p>
								</div>
								<button
									className="flex h-10 w-10 items-center justify-center rounded-full bg-gray-100 text-gray-800 transition-colors hover:bg-gray-800 hover:text-white"
									onClick={() => addToCart(product)}
									type="button"
								>
									<Plus className="h-5 w-5" />
								</button>
							</div>
						))}
					</div>
				</div>
			</div>

			{cartCount > 0 && (
				<button
					className="fixed bottom-6 left-1/2 -translate-x-1/2 flex w-[90%] max-w-md items-center justify-between rounded-2xl bg-gray-800 px-6 py-4 text-white shadow-xl"
					onClick={() => setShowCart(!showCart)}
					type="button"
				>
					<div className="flex items-center gap-3">
						<div className="flex h-8 w-8 items-center justify-center rounded-full bg-white/20 font-bold">
							{cartCount}
						</div>
						<span className="font-bold">Rp {cartTotal.toLocaleString("id-ID")}</span>
					</div>
					<span className="font-bold">Checkout →</span>
				</button>
			)}

			{showCart && cartCount > 0 && (
				<div className="fixed inset-0 z-50 flex items-end justify-center bg-black/50" onClick={() => setShowCart(false)}>
					<div className="w-full max-w-md rounded-t-2xl bg-white p-6" onClick={(e) => e.stopPropagation()}>
						<div className="mb-4 flex items-center justify-between">
							<h2 className="text-xl font-bold">Keranjang</h2>
							<button className="rounded-full bg-gray-100 p-2" onClick={() => setShowCart(false)} type="button">
								×
							</button>
						</div>
						<div className="space-y-4">
							{cart.map((item) => (
								<div className="flex items-center justify-between" key={item.productId}>
									<div>
										<p className="font-bold">{item.name}</p>
										<p className="text-sm text-gray-500">Rp {item.price.toLocaleString("id-ID")} x {item.quantity}</p>
									</div>
									<div className="flex items-center gap-2">
										<button className="rounded-full border p-1" onClick={() => updateQuantity(item.productId, -1)} type="button">
											<Minus className="h-4 w-4" />
										</button>
										<span className="w-6 text-center">{item.quantity}</span>
										<button className="rounded-full border p-1" onClick={() => updateQuantity(item.productId, 1)} type="button">
											<Plus className="h-4 w-4" />
										</button>
									</div>
								</div>
							))}
						</div>
						<div className="mt-4 border-t pt-4">
							<div className="mb-4 flex justify-between text-lg font-bold">
								<span>Total</span>
								<span>Rp {cartTotal.toLocaleString("id-ID")}</span>
							</div>
							<button className="w-full rounded-xl bg-gray-800 py-3 font-bold text-white" type="button">
								Pesan Sekarang
							</button>
						</div>
					</div>
				</div>
			)}
		</div>
	);
}
